使用可选绑定或可选链安全处理：
```swift
// 危险
let name = user.name!  // nil时crash
let image = UIImage(named: "icon")!

// 安全 - 可选绑定
if let name = user.name {
    print(name)
}

// 安全 - guard let提前退出
guard let name = user.name else { return }

// 安全 - nil合并
let name = user.name ?? "Unknown"

// 仅在以下场景使用!：
// IBOutlet（Storyboard保证非nil）
// fatalError场景
// 单元测试中的precondition
```

优先使用普通Optional或确保初始化：
```swift
// 不推荐 - IUO滥用
var userName: String!
var dataSource: [Item]!

// 推荐 - 明确可选或提供默认值
var userName: String?        // 明确可选
var dataSource: [Item] = []   // 确保初始化

// 仅在合理场景使用IUO：
// @IBOutlet var label: UILabel!  // IB保证连接后非nil
// weak var delegate: Protocol!   // 明确的弱引用生命周期
```

在闭包中使用[weak self]打破循环引用：
```swift
// 危险 - 循环引用
class ViewController: UIViewController {
    var timer: Timer?

    func startTimer() {
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { _ in
            self.updateLabel() // self被闭包强引用 -> 循环引用
        }
    }
}

// 正确 - weak self
class ViewController: UIViewController {
    func startTimer() {
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
            self?.updateLabel() // weak不增加引用计数
        }
    }
}

// URLSession类似处理
URLSession.shared.dataTask(with: url) { [weak self] data, _, _ in
    guard let self = self else { return }
    DispatchQueue.main.async {
        self.label.text = String(data: data!, encoding: .utf8)
    }
}.resume()
```

使用Keychain存储敏感数据：
```swift
// 危险 - 明文存储
UserDefaults.standard.set(token, forKey: "auth_token")
UserDefaults.standard.set(password, forKey: "password")

// 安全 - 使用Keychain
import Security

func saveToKeychain(key: String, data: Data) -> OSStatus {
    let query: [String: Any] = [
        kSecClass as String: kSecClassGenericPassword,
        kSecAttrAccount as String: key,
        kSecValueData as String: data
    ]
    SecItemDelete(query as CFDictionary)
    return SecItemAdd(query as CFDictionary, nil)
}

// 或使用第三方库
// KeychainAccess
let keychain = Keychain()
try? keychain.set(token, key: "auth_token")
```

实现证书校验或至少校验证书指纹：
```swift
// 危险 - 信任所有证书
func urlSession(_ session: URLSession, didReceive challenge: URLAuthenticationChallenge,
    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
    completionHandler(.useCredential, URLCredential(trust: challenge.protectionSpace.serverTrust!))
}

// 安全 - 证书固定（Certificate Pinning）
func urlSession(_ session: URLSession, didReceive challenge: URLAuthenticationChallenge,
    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
    guard let trust = challenge.protectionSpace.serverTrust,
          let certificate = SecTrustGetCertificateAtIndex(trust, 0) else {
        completionHandler(.cancelAuthenticationChallenge, nil)
        return
    }

    let remoteCertData = SecCertificateCopyData(certificate) as Data
    let pinnedCertData = Bundle.main.url(forResource: "cert", withExtension: "der")
        .flatMap { try? Data(contentsOf: $0) }

    if remoteCertData == pinnedCertData {
        completionHandler(.useCredential, URLCredential(trust: trust))
    } else {
        completionHandler(.cancelAuthenticationChallenge, nil)
    }
}
```

使用perform/performAndWait确保线程安全：
```swift
// 危险 - 后台线程操作main context
dispatchQueue.global().async {
    let objects = try mainContext.fetch(request) // 错误线程！
}

// 安全 - 使用perform
mainContext.perform {
    let objects = try? mainContext.fetch(request)
}

// 更推荐 - 为后台操作创建独立context
let backgroundContext = NSManagedObjectContext(concurrencyType: .privateQueueConcurrencyType)
backgroundContext.parent = mainContext

backgroundContext.perform {
    // 后台安全操作
    let objects = try? backgroundContext.fetch(request)
    try? backgroundContext.save() // 保存到parent

    mainContext.perform {
        // 在主context中处理更新
    }
}
```

正确实现UIApplicationDelegate生命周期方法：
```swift
// 在AppDelegate或SceneDelegate中实现
class AppDelegate: UIResponder, UIApplicationDelegate {
    func applicationDidEnterBackground(_ application: UIApplication) {
        // 保存用户数据、暂停任务
        saveUnsavedData()

        // 需要更多后台时间时
        var bgTask = UIBackgroundTaskIdentifier.invalid
        bgTask = application.beginBackgroundTask { 
            application.endBackgroundTask(bgTask)
        }
        DispatchQueue.global().async {
            performCleanup()
            application.endBackgroundTask(bgTask)
        }
    }

    func applicationWillTerminate(_ application: UIApplication) {
        // 最终保存
        saveUnsavedData()
    }

    func didReceiveMemoryWarning() {
        // 释放缓存
        imageCache.removeAll()
    }
}
```
